import { forEach, trueValue } from "@alova/shared";
import { computed, getCurrentInstance, onMounted, onUnmounted, ref, watch } from "vue-demi";
//#region src/statesHook/vue-demi.ts
var vue_demi_default = {
	name: "VueDemi",
	create: (data) => ref(data),
	dehydrate: (state) => state.value,
	update: (newVal, state) => {
		state.value = newVal;
	},
	effectRequest({ handler, immediate, watchingStates }) {
		immediate && handler();
		forEach(watchingStates || [], (state, i) => {
			watch(state, () => {
				handler(i);
			}, { deep: trueValue });
		});
	},
	computed: (getter) => computed(getter),
	watch: (states, callback) => {
		watch(states, callback, { deep: trueValue });
	},
	onMounted: (callback) => {
		getCurrentInstance() && onMounted(callback);
	},
	onUnmounted: (callback) => {
		onUnmounted(callback);
	}
};
//#endregion
export { vue_demi_default as default };
